DROP TABLE IF EXISTS `view_earnings_reactions_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_earnings_reactions_summary`  AS SELECT `event_reactions`.`symbol` AS `symbol`, `event_reactions`.`earnings_date` AS `earnings_date`, `event_reactions`.`price_before` AS `price_before`, `event_reactions`.`price_after` AS `price_after`, `event_reactions`.`pct_change` AS `pct_change` FROM `event_reactions``event_reactions`  ;

