--
-- Estrutura para vista `view_stock_window_details`
--
DROP TABLE IF EXISTS `view_stock_window_details`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_stock_window_details`  AS SELECT `e`.`symbol` AS `symbol`, `e`.`earnings_date` AS `earnings_date`, `s`.`date` AS `date`, `s`.`price` AS `price`, `s`.`volume` AS `volume`, to_days(`s`.`date`) - to_days(`e`.`earnings_date`) AS `days_from_event` FROM (`earnings_reports` `e` join `stock_prices` `s` on(`s`.`symbol` = `e`.`symbol`)) WHERE to_days(`s`.`date`) < to_days(`e`.`earnings_date`) + 3 AND to_days(`s`.`date`) > to_days(`e`.`earnings_date`) - 33  ;

